<?php require __DIR__.'/bootstrap.php';$u=uid();$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$a=(string)($_POST['action']??'');try{
if($a==='save'){$id=(int)($_POST['id']??0);$title=trim((string)($_POST['title']??''));$body=(string)($_POST['body']??'');if(strlen($body)>2000000)throw new RuntimeException('Note exceeds 2 MB');$cat=safe_cat((int)($_POST['category_id']??0),$u);$newcat=trim((string)($_POST['new_category']??''));$newsub=trim((string)($_POST['new_subcategory']??''));if($newcat!=='')$cat=getcat($u,$newcat,null);if($newsub!=='')$cat=getcat($u,$newsub,$cat);$kind=($_POST['kind']??'text')==='checklist'?'checklist':'text';$tags=(string)($_POST['tags']??'');
if(!$id){$exact=q('SELECT id,title FROM mn_notes WHERE user_id=? AND trashed_at IS NULL AND title=? AND body=? LIMIT 1',[$u,$title,$body])->fetch();if($exact&&($_POST['duplicate_override']??'')!=='1')throw new RuntimeException('Exact duplicate found: note #'.$exact['id'].'. Choose “Save anyway” to keep both.');$similar=q('SELECT id,title FROM mn_notes WHERE user_id=? AND trashed_at IS NULL AND title=? AND title<>\'\' LIMIT 1',[$u,$title])->fetch();if($similar&&($_POST['duplicate_override']??'')!=='1')throw new RuntimeException('A note with the same title exists (#'.$similar['id'].'). Review it before saving, or choose “Save anyway”.');q('INSERT INTO mn_notes(user_id,category_id,title,body,kind) VALUES(?,?,?,?,?)',[$u,$cat,$title,$body,$kind]);$id=(int)db()->lastInsertId();}else{q('UPDATE mn_notes SET title=?,body=?,category_id=?,kind=? WHERE id=? AND user_id=?',[$title,$body,$cat,$kind,$id,$u]);}set_tags($u,$id,$tags);go('index.php?saved=1');}
if(in_array($a,['pin','archive','trash','restore'],true)){$id=(int)($_POST['id']??0);$col=['pin'=>'pinned','archive'=>'archived'][$a]??null;if($col)q("UPDATE mn_notes SET $col=1-$col WHERE id=? AND user_id=?",[$id,$u]);elseif($a==='trash')q('UPDATE mn_notes SET trashed_at=NOW() WHERE id=? AND user_id=?',[$id,$u]);else q('UPDATE mn_notes SET trashed_at=NULL WHERE id=? AND user_id=?',[$id,$u]);go();}
if($a==='bulk'){
$ids=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['note_ids']??[])),fn($v)=>$v>0)));
if(!$ids||count($ids)>300)throw new RuntimeException('Select between 1 and 300 notes.');
$op=(string)($_POST['bulk_operation']??'');
if(!in_array($op,['category','trash'],true))throw new RuntimeException('Invalid bulk action.');
$placeholders=implode(',',array_fill(0,count($ids),'?'));
$valid=q('SELECT id FROM mn_notes WHERE user_id=? AND trashed_at IS NULL AND id IN ('.$placeholders.')',array_merge([$u],$ids))->fetchAll(PDO::FETCH_COLUMN);
if(count($valid)!==count($ids))throw new RuntimeException('Some selected notes are unavailable. Refresh and try again.');
if($op==='category'){
$requested=(int)($_POST['bulk_category_id']??0);
$cat=safe_cat($requested,$u);
if($requested!==0&&$cat===null)throw new RuntimeException('Category not found.');
q('UPDATE mn_notes SET category_id=? WHERE user_id=? AND trashed_at IS NULL AND id IN ('.$placeholders.')',array_merge([$cat,$u],$ids));
}else{
q('UPDATE mn_notes SET trashed_at=NOW() WHERE user_id=? AND trashed_at IS NULL AND id IN ('.$placeholders.')',array_merge([$u],$ids));
}
go('index.php?bulk_done='.($op==='trash'?'trash':'category'));
}
if($a==='category'){$parent=safe_cat((int)($_POST['parent_id']??0),$u);getcat($u,(string)($_POST['name']??''),$parent);go();}
}catch(Throwable $e){$error=$e->getMessage();}}
$view=(string)($_GET['view']??'active');$catFilter=(int)($_GET['cat']??0);$search=trim((string)($_GET['q']??''));$categories=q('SELECT * FROM mn_categories WHERE user_id=? ORDER BY parent_id IS NOT NULL,parent_id,name',[$u])->fetchAll();$selectedCats=array_values(array_unique(array_filter(array_map('intval',explode(',',(string)($_COOKIE['mn_visible_cats']??''))),function($id){return $id>0;})));$validCats=array_column($categories,'id');$selectedCats=array_values(array_intersect($selectedCats,array_map('intval',$validCats)));$visibleCats=$selectedCats;do{$before=count($visibleCats);foreach($categories as $c){if($c['parent_id']!==null&&in_array((int)$c['parent_id'],$visibleCats,true)&&!in_array((int)$c['id'],$visibleCats,true))$visibleCats[]=(int)$c['id'];}}while(count($visibleCats)>$before);$where='n.user_id=?';$params=[$u];if($view==='trash')$where.=' AND n.trashed_at IS NOT NULL';else{$where.=' AND n.trashed_at IS NULL';$where.=$view==='archive'?' AND n.archived=1':' AND n.archived=0';}if($view==='active' && $search===''){$where.=' AND (n.pinned=1';if(!$visibleCats)$where.=' OR n.category_id IS NULL';if($visibleCats){$where.=' OR n.category_id IN ('.implode(',',array_fill(0,count($visibleCats),'?')).')';array_push($params,...$visibleCats);}$where.=')';}if($search!==''){$where.=' AND (n.title LIKE ? OR n.body LIKE ?)';$like='%'.$search.'%';array_push($params,$like,$like);}$notes=q('SELECT n.*,c.name AS category_name FROM mn_notes n LEFT JOIN mn_categories c ON c.id=n.category_id WHERE '.$where.' ORDER BY n.pinned DESC,n.updated_at DESC LIMIT 300',$params)->fetchAll();$editing=null;if(isset($_GET['edit']))$editing=q('SELECT * FROM mn_notes WHERE id=? AND user_id=?',[(int)$_GET['edit'],$u])->fetch();
?><!doctype html><html lang="en"><head><link rel="icon" type="image/png" href="favicon.png"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MyNotes</title><link rel="stylesheet" href="style.css"><script src="app.js" defer></script></head><body><header><button class="menu" type="button" id="menu">☰</button><a class="brand" href="index.php">My<span>Notes</span></a><form class="search" method="get"><input name="q" placeholder="Search notes..." value="<?=h($search)?>"><button>Search</button></form><a href="import.php">Import</a><?php if(!empty($_SESSION['admin'])):?><a href="admin/">Admin</a><?php endif;?><a href="logout.php">Sign out</a></header><div class="layout"><aside id="sidebar"><a href="index.php">▦ All Notes</a><a href="?view=archive">▤ Archive</a><a href="?view=trash">▥ Trash</a><h3>Categories</h3><?php foreach($categories as $c):?><label class="cat-choice <?= $c['parent_id']?'sub':'' ?>"><input type="checkbox" class="cat-filter" value="<?=$c['id']?>" <?=in_array((int)$c['id'],$selectedCats,true)?'checked':''?>><?=h($c['name'])?></label><?php endforeach;?><form method="post" class="category-form"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="category"><input name="name" maxlength="160" placeholder="New category" required><select name="parent_id"><option value="0">Top-level</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>"><?=h($c['name'])?></option><?php endforeach;?></select><button>Add category</button></form></aside><main><div class="topline"><h1><?= $view==='archive'?'Archive':($view==='trash'?'Trash':'My Notes')?></h1><div class="top-actions"><button type="button" id="selectNotes">Select notes</button><button type="button" id="newNote">+ New note</button></div></div><?php if($error):?><p class="error"><?=h($error)?></p><?php endif;?><?php if(isset($_GET['saved'])):?><p class="notice">Note saved.</p><?php endif;?><?php if(isset($_GET['bulk_done'])):?><p class="notice"><?=($_GET['bulk_done']==='trash')?'Selected notes moved to Trash.':'Selected notes moved to category.'?></p><?php endif;?>
<form method="post" id="bulkForm" class="bulk-toolbar" hidden><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="bulk"><input type="hidden" name="bulk_operation" id="bulkOperation" value=""><span id="selectedCount">0 selected</span><button type="button" id="selectAllVisible">Select all visible</button><select name="bulk_category_id" id="bulkCategory"><option value="" selected disabled>Choose category...</option><option value="0">Uncategorized</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>"><?=h(($c['parent_id']?'↳ ':'').$c['name'])?></option><?php endforeach;?></select><button type="button" id="bulkMove">Move to category</button><button type="button" id="bulkTrash">Trash selected</button><button type="button" id="cancelSelection">Cancel</button></form><section class="cards"><?php foreach($notes as $n):?><article class="note"><label class="bulk-check" hidden><input type="checkbox" name="note_ids[]" value="<?=$n['id']?>" form="bulkForm" aria-label="Select <?=h($n['title']?:'Untitled')?>"></label><a href="?edit=<?=$n['id']?>"><h2><?=h($n['title']?:'Untitled')?></h2><p><?=h(mb_strimwidth($n['body'],0,400,'…'))?></p></a><div class="meta"><?=h($n['category_name']??'Uncategorized')?> · <?=h($n['updated_at'])?></div><div class="actions"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="id" value="<?=$n['id']?>"><?php if($view==='trash'):?><button name="action" value="restore">Restore</button><?php else:?><button name="action" value="pin"><?=$n['pinned']?'Unpin':'Pin'?></button><button name="action" value="archive"><?=$n['archived']?'Unarchive':'Archive'?></button><button name="action" value="trash" data-confirm="Move note to trash?">Trash</button><?php endif;?></form></div></article><?php endforeach;?></section><?php if(!$notes):?><p class="muted">No notes found.</p><?php endif;?></main></div>
